package co.edu.cinematch.core.model;
import java.time.LocalDateTime;
public class Pago implements Identifiable { private String id,reservaId,metodoPago,estado; private double monto; private LocalDateTime fecha; public Pago(){} public Pago(String reservaId,String metodoPago,double monto,LocalDateTime fecha,String estado){this.reservaId=reservaId;this.metodoPago=metodoPago;this.monto=monto;this.fecha=fecha;this.estado=estado;} public String getId(){return id;}public void setId(String v){id=v;}public String getReservaId(){return reservaId;}public void setReservaId(String v){reservaId=v;}public String getMetodoPago(){return metodoPago;}public void setMetodoPago(String v){metodoPago=v;}public double getMonto(){return monto;}public void setMonto(double v){monto=v;}public LocalDateTime getFecha(){return fecha;}public void setFecha(LocalDateTime v){fecha=v;}public String getEstado(){return estado;}public void setEstado(String v){estado=v;} }
